const input = $json.body ?? $json;
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : null; };

const dealId = input.deal_id;
const leadId = input.lead_id;
const propertyId = input.property_id;
const adjustedMao = num(input.adjusted_mao ?? input.dynamic_mao);
const askingPrice = num(input.asking_price);
const projectedProfit = num(input.projected_assignment_profit ?? input.projected_profit);
const motivation = String(input.motivation ?? "").toLowerCase();
const assetClass = String(input.asset_class ?? input.asset_type ?? "residential_wholesale").toLowerCase();
const blockers = Array.isArray(input.blockers) ? input.blockers : [];
const evidenceStatus = String(input.evidence_status ?? "complete").toLowerCase();
const dnc = input.dnc === true || input.do_not_contact === true;
const confidence = String(input.confidence ?? "").toLowerCase();

const identityReady = Boolean(dealId && leadId && propertyId);
const maoReady = adjustedMao !== null && adjustedMao >= 0;
const askingReady = askingPrice !== null && askingPrice >= 0;
const profitReady = projectedProfit !== null;
const evidenceReady = !["missing", "incomplete", "failed", "insufficient"].includes(evidenceStatus);
const blocked = dnc || blockers.length > 0;

const assetAware = assetClass.includes("land")
  ? "land_development_and_exit_economics"
  : assetClass.includes("multi") || assetClass.includes("apartment")
    ? "multifamily_cashflow_and_exit_economics"
    : "residential_wholesale_assignment_economics";

let decision = "needs_evidence";
let reason = "Required evidence or underwriting inputs are incomplete.";
let nextWorkflow = "WF-332";

if (!identityReady || !maoReady || !askingReady || !profitReady || !evidenceReady) {
  decision = "needs_evidence";
  reason = "Property identity, dynamic MAO, asking price, projected profit, or evidence is incomplete.";
} else if (blocked) {
  decision = "blocked";
  reason = "DNC or active blockers prevent acquisition action.";
  nextWorkflow = "WF-126";
} else {
  const positiveProfit = projectedProfit > 0;
  const atOrBelowMao = askingPrice <= adjustedMao;
  const negotiationBand = askingPrice > adjustedMao && askingPrice <= adjustedMao * 1.10 && positiveProfit;

  if (atOrBelowMao && positiveProfit) {
    decision = "pursue";
    reason = "Asking price is at or below dynamic MAO and projected economics are profitable.";
    nextWorkflow = "WF-334";
  } else if (negotiationBand) {
    decision = "negotiate";
    reason = "Asking price is above dynamic MAO but within the controlled negotiation band with positive projected profit.";
    nextWorkflow = "WF-334";
  } else if (!positiveProfit || askingPrice > adjustedMao * 1.10) {
    decision = "pass";
    reason = "Projected economics do not support acquisition at the current asking price.";
    nextWorkflow = "WF-335";
  }
}

const sellerPriority =
  motivation.includes("high") || motivation.includes("urgent") || motivation.includes("distress")
    ? "high"
    : motivation.includes("medium") || motivation.includes("moderate")
      ? "medium"
      : "standard";

return [{
  json: {
    ...input,
    workflow_id: "WF-333",
    controller_status: decision,
    acquisition_decision: decision,
    deal_id: dealId,
    lead_id: leadId,
    property_id: propertyId,
    asset_class: assetClass,
    asset_economics_strategy: assetAware,
    adjusted_mao: adjustedMao,
    asking_price: askingPrice,
    projected_assignment_profit: projectedProfit,
    seller_priority: sellerPriority,
    confidence,
    evidence_status: evidenceStatus,
    reason,
    next_workflow: nextWorkflow,
    requires_human_review: decision === "negotiate" || decision === "blocked" || decision === "needs_evidence",
    hard_mao_guardrail: true,
    rule_70_percent: "secondary_reference_only",
    idempotency_key: input.idempotency_key ?? \`wf-333:\${dealId ?? "unknown"}:\${propertyId ?? "unknown"}:\${adjustedMao ?? "unknown"}:\${askingPrice ?? "unknown"}\`
  }
}];
